    channelId: "playground",
    mode: "chat",
    purpose: "live",
    continuationKey: "cont_key_1",
    auth: { kind: "user", userId: 42 },
    title: "Weather in NYC",
    turnCount: 3,
    createdAt: "2026-08-01T12:00:00.000Z",
    updatedAt: "2026-08-01T12:05:00.000Z",
    extraUnknownField: { nested: true },
